css:
.chat {
  display: flex;
  gap: 40px;
  padding: 32px 32px 48px;
  font-family: system-ui, sans-serif;
}

.bubble {
  position: relative;
  max-width: 220px;
  margin: 0;
  padding: 14px 16px;
  border-radius: 12px;
  background-color: #ffffff;
  line-height: 1.4;
}

.bubble::after {
  content: "";
  position: absolute;
  bottom: -8px;
  left: 28px;
  width: 18px;
  height: 18px;
  background-color: #ffffff;
  transform: rotate(45deg);
}

.boxed {
  box-shadow: 0 6px 10px rgb(0 0 0 / 0.35);
}

.dropped {
  filter: drop-shadow(0 6px 5px rgb(0 0 0 / 0.35));
}
